const visual = {
  prepare: function (input) { return [{ kind: 'text', payload: '题面文字' }]; },
  render: function (input, metrics) {
    var w = input.viewport.widthDu, h = input.viewport.heightDu;
    return { schemaVersion: 1, sceneId: 'cal', revision: input.revision,
             viewBox: { x: 0, y: 0, width: w, height: h },
             paths: [{ id: 'check', commands: visualSdk.polyline([[100, 140], [140, 180], [220, 80]]) }],
             root: { type: 'group', children: [
               { type: 'path', pathId: 'check', fill: '#cc2222', stroke: { width: 5 } }, { type: 'label', contentId: metrics[0].contentId, anchor: { x: 180, y: 40 }, hAlign: 'center', vAlign: 'top', color: '#26354a' } ] } };
  },
};
